window.ScripturaLexicons.BDAG_PART_0154 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-euprasso-bdag\" data-source=\"BDAG\" data-search=\"εὐπράσσω euprássō verbo remissivo ver εὖ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐπράσσω</td><td>verbo remissivo</td><td>ver εὖ</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-euprepeia-bdag\" data-source=\"BDAG\" data-search=\"εὐπρέπεια, ας, ἡ euprépeia substantivo feminino bela aparência; beleza BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐπρέπεια, ας, ἡ</td><td>substantivo feminino</td><td>bela aparência; beleza</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-euprepes-bdag\" data-source=\"BDAG\" data-search=\"εὐπρεπής, ές euprepḗs adjetivo de bela aparência; magnífico; harmonioso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐπρεπής, ές</td><td>adjetivo</td><td>de bela aparência; magnífico; harmonioso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-euprepos-bdag\" data-source=\"BDAG\" data-search=\"εὐπρεπῶς euprepôs advérbio de modo atraente; apropriadamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐπρεπῶς</td><td>advérbio</td><td>de modo atraente; apropriadamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-euprosdektos-bdag\" data-source=\"BDAG\" data-search=\"εὐπρόσδεκτος, ον euprósdektos adjetivo aceitável; bem-vindo; favorável BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐπρόσδεκτος, ον</td><td>adjetivo</td><td>aceitável; bem-vindo; favorável</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-euprosedros-bdag\" data-source=\"BDAG\" data-search=\"εὐπρόσεδρος, ον euprosédros adjetivo assíduo; constantemente dedicado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐπρόσεδρος, ον</td><td>adjetivo</td><td>assíduo; constantemente dedicado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-euprosopeo-bdag\" data-source=\"BDAG\" data-search=\"εὐπροσωπέω euprosōpéō verbo causar boa impressão; apresentar boa aparência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐπροσωπέω</td><td>verbo</td><td>causar boa impressão; apresentar boa aparência</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eurakylon-bdag\" data-source=\"BDAG\" data-search=\"εὐρακύλων, ωνος, ὁ eurakýlōn substantivo masculino euraquilão; vento nordeste BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐρακύλων, ωνος, ὁ</td><td>substantivo masculino</td><td>euraquilão; vento nordeste</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heureteos-bdag\" data-source=\"BDAG\" data-search=\"εὑρετέος, α, ον heuretéos adjetivo verbal que deve ser encontrado; que se deve descobrir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὑρετέος, α, ον</td><td>adjetivo verbal</td><td>que deve ser encontrado; que se deve descobrir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heurema-bdag\" data-source=\"BDAG\" data-search=\"εὕρημα, ατος, τό heúrēma substantivo neutro descoberta; invenção BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὕρημα, ατος, τό</td><td>substantivo neutro</td><td>descoberta; invenção</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heurisko-bdag\" data-source=\"BDAG\" data-search=\"εὑρίσκω heurískō verbo encontrar; descobrir; obter; ser encontrado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὑρίσκω</td><td>verbo</td><td>encontrar; descobrir; obter; ser encontrado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-euroklydon-bdag\" data-source=\"BDAG\" data-search=\"εὐροκλύδων, ωνος, ὁ euroklýdōn substantivo masculino euroclidom; vento sudeste que levanta ondas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐροκλύδων, ωνος, ὁ</td><td>substantivo masculino</td><td>euroclidom; vento sudeste que levanta ondas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-euryklydon-bdag\" data-source=\"BDAG\" data-search=\"εὐρυκλύδων euryklýdōn forma remissiva ver εὐροκλύδων BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐρυκλύδων</td><td>forma remissiva</td><td>ver εὐροκλύδων</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eurychoros-bdag\" data-source=\"BDAG\" data-search=\"εὐρύχωρος, ον eurýchōros adjetivo amplo; espaçoso; de grande extensão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐρύχωρος, ον</td><td>adjetivo</td><td>amplo; espaçoso; de grande extensão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eusebeia-bdag\" data-source=\"BDAG\" data-search=\"εὐσέβεια, ας, ἡ eusébeia substantivo feminino reverência a Deus; piedade; devoção; atos de piedade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐσέβεια, ας, ἡ</td><td>substantivo feminino</td><td>reverência a Deus; piedade; devoção; atos de piedade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eusebeo-bdag\" data-source=\"BDAG\" data-search=\"εὐσεβέω eusebéō verbo reverenciar; prestar culto; respeitar profundamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐσεβέω</td><td>verbo</td><td>reverenciar; prestar culto; respeitar profundamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eusebes-bdag\" data-source=\"BDAG\" data-search=\"εὐσεβής, ές eusebḗs adjetivo devoto; piedoso; reverente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐσεβής, ές</td><td>adjetivo</td><td>devoto; piedoso; reverente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eusebos-bdag\" data-source=\"BDAG\" data-search=\"εὐσεβῶς eusebôs advérbio piedosamente; de maneira reverente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐσεβῶς</td><td>advérbio</td><td>piedosamente; de maneira reverente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eusemos-bdag\" data-source=\"BDAG\" data-search=\"εὔσημος, ον eúsēmos adjetivo claro; inteligível; distinto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὔσημος, ον</td><td>adjetivo</td><td>claro; inteligível; distinto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eusplanchnia-bdag\" data-source=\"BDAG\" data-search=\"εὐσπλαγχνία, ας, ἡ eusplanchnía substantivo feminino compaixão; ternura; benevolência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐσπλαγχνία, ας, ἡ</td><td>substantivo feminino</td><td>compaixão; ternura; benevolência</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article id=\"entry-euprasso-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐπράσσω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦euprássō⟧</span><span class=\"separator\">·</span><span>verbo remissivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐπράσσω</span>. <strong>Ver <span class=\"greek\">εὖ</span>.</strong> Entrada remissiva autônoma do BDAG; o original não fornece outras acepções, paradigmas ou testemunhos nesta entrada.</p></section></article>\n<article id=\"entry-euprepeia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐπρέπεια, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦euprépeia⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐπρέπεια</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span>. Ver os dois verbetes seguintes e <span class=\"greek\">πρέπω</span>. Tucídides e posteriores; Epicteto 1, 8, 7; SIG 358; 880, 17; LXX; TestSol; TestAbr A 16, p. 98, 1 [Stone p. 44]; TestJob; TestNapht 2:8; Fílon, Aet. M. 126; Josefo, Ant. 4, 131; Taciano 1:2. <strong>Bela aparência; beleza</strong>, ApcPt 3:10. <span class=\"greek\">ἡ</span> <span class=\"greek\">εὐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">προσώπου</span> <span class=\"greek\">αὐτοῦ</span>, «a beleza da aparência dela [isto é, da flor]», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1:11</a>. <span class=\"greek\">περιτιθέναι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">εὐ</span>. <span class=\"greek\">τινι</span>, «revestir alguma coisa de beleza», Hv 1, 3, 4. Bibliografia: DELG, s.v. <span class=\"greek\">πρέπω</span>; M-M; Spicq.</p></section></article>\n<article id=\"entry-euprepes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐπρεπής, ές</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦euprepḗs⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐπρεπής</span>, <span class=\"greek\">ές</span>; genitivo <span class=\"greek\">οῦς</span>. Ver o verbete precedente e <span class=\"greek\">πρέπω</span>. Ésquilo, Heródoto e posteriores; Diodoro Sículo 1, 45, 4, edição Vogel, variante textual [o texto traz <span class=\"greek\">ναοῖς</span> <span class=\"greek\">ἐκπρεπέσι</span>]; Epicteto 1, 2, 18 e outros; inscrições; POxy 1380, 130 [séc. II d.C.]; LXX; TestAbr A; JosAs; Fílon; Josefo, Ant. 6, 160; Atenágoras 33, 2.</p><p class=\"entry-text\"><strong>Comparativo <span class=\"greek\">εὐπρεπέστερος</span></strong>, «mais belo» (Ésquilo e outros; Wsd 7:29): Dg 2:2; Hs 5, 2, 4. <strong>Superlativo <span class=\"greek\">εὐπρεπέστατος</span></strong>, «belíssimo; o mais belo» (Heródoto e outros; TestAbr A 2, p. 78, 18 [Stone p. 4]; Josefo, Ant. 1, 200): Hs 2:1; 9, 1, 10; 9, 10, 3.</p><p class=\"entry-text\">① <strong>Que apresenta aparência atraente: vistoso; de bela aparência.</strong> De uma vinha cuidadosamente revolvida e limpa: <span class=\"greek\">εὐπρεπέστερος</span> <span class=\"greek\">ἔσται</span>, «terá aparência melhor», Hs 5, 2, 4. De uma montanha branca: <span class=\"greek\">εὐπρεπέστατον</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄρος</span>, «a montanha, por si só [sem árvores], era belíssima», Hs 9, 1, 10. De um local limpo: «muito atraente», Hs 9, 10, 3. De um edifício: <strong>magnífico</strong>, Hs 9, 9, 7. <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">εὐπρεπέστερον</span>, seguido de genitivo, «nada mais belo de se ver do que», Dg 2:2.</p><p class=\"entry-text\">② <strong>Que é compatível ou harmonioso: apropriado; bem ajustado</strong>, com dativo <span class=\"greek\">τινί</span>, «a alguma coisa». Do olmo e da videira: <span class=\"greek\">εὐπρεπέσταταί</span> <span class=\"greek\">εἰσιν</span> <span class=\"greek\">ἀλλήλαις</span>, «estão muitíssimo bem ajustados um ao outro», Hs 2:1.</p></section></article>\n<article id=\"entry-euprepos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐπρεπῶς</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦euprepôs⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐπρεπῶς</span>, advérbio derivado de <span class=\"greek\">εὐπρεπής</span>. Ver os dois verbetes precedentes. Ésquilo e outros; SIG 1109, 110; 1Esd 1:10; Wsd 13:11; Josefo, Ant. 13, 31.</p><p class=\"entry-text\">① <strong>De maneira que produz bela aparência: de modo atraente</strong>, Hs 5, 2, 5. Esse sentido também foi proposto para Hs 9, 2, 4; contudo, o contexto parece exigir o seguinte:</p><p class=\"entry-text\">② <strong>Em conformidade com o que se espera: convenientemente; apropriadamente.</strong> Acerca de mulheres: <span class=\"greek\">περιεζωσμέναι</span> <span class=\"greek\">ἦσαν</span> <span class=\"greek\">εὐ</span>., «estavam cingidas apropriadamente». O original, nesta entrada, não oferece outra indicação explícita após essa expressão.</p></section></article>\n<article id=\"entry-euprosdektos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐπρόσδεκτος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦euprósdektos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐπρόσδεκτος</span>, <span class=\"greek\">ον</span>. «(Facilmente) aceitável; agradável; bem-vindo». Ver <span class=\"greek\">προσδέχομαι</span>; Plutarco, Mor. 801c.</p><p class=\"entry-text\">① <strong>Que é capaz de obter acolhimento favorável: aceitável.</strong></p><p class=\"entry-text\">ⓐ <strong>De coisas:</strong> ofertas (escólio a Aristófanes, Pax 1054 <span class=\"greek\">εὐπρόσδεκτος</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">θυσία</span>, «o sacrifício é aceitável»); <span class=\"greek\">προσφορά</span>, «oferta», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15:16</a>. De pessoas, 1Cl 40:4. Da disposição para contribuir, considerada aceitável, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 8:12</a>.</p><p class=\"entry-text\"><strong>Com dativo da pessoa para quem algo é aceitável:</strong> para seres humanos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.31\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15:31</a>; para Deus, <span class=\"greek\">θυσίαι</span> <span class=\"greek\">εὐ</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, «sacrifícios aceitáveis a Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 2:5</a> (cf. Vi. Aesopi W 8 P. <span class=\"greek\">εὐπρόσδεκτον</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀγαθοποιεῖν</span>, «fazer o bem é aceitável diante de Deus»; Cat. Cod. Astr. VII 178, 6 <span class=\"greek\">εὐ</span>. <span class=\"greek\">αἱ</span> <span class=\"greek\">εὐχαὶ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">θεόν</span>, «as orações são aceitáveis a Deus»; SIG 1042, 8 <span class=\"greek\">ἀπρόσδεκτος</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">θυσία</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>, «sacrifício não aceito por Deus»). <span class=\"greek\">ἱλαρότης</span>, «alegria», Hm 10, 3, 1. <span class=\"greek\">λειτουργία</span>, «serviço», Hs 5, 3, 8. <span class=\"greek\">εὐ</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">θελήματι</span> <span class=\"greek\">αὐτοῦ</span>, «aceitável à sua vontade», 1Cl 40:3; <span class=\"greek\">τὰ</span> <span class=\"greek\">εὐ</span>., «as coisas aceitáveis a Deus», 1Cl 35:5.</p><p class=\"entry-text\">ⓑ <strong>De pessoas:</strong> 1Cl 40:4.</p><p class=\"entry-text\">② <strong>Que é bem-vindo numa situação: favorável; propício.</strong> De um tempo favorável à realização da graça de Deus: <span class=\"greek\">καιρὸς</span> <span class=\"greek\">εὐ</span>., «tempo favorável», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 6:2</a>. Bibliografia: DELG, s.v. <span class=\"greek\">δέχομαι</span>; M-M; TW; Spicq.</p></section></article>\n<article id=\"entry-euprosedros-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐπρόσεδρος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦euprosédros⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐπρόσεδρος</span>, <span class=\"greek\">ον</span>. Ver <span class=\"greek\">προσεδρεύω</span>, «prestar assistência; atender continuamente». <strong>Que presta assistência constante: assíduo; permanentemente dedicado ao serviço</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.35\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 7:35</a>, variante de leitura (ver <span class=\"greek\">εὐπάρεδρος</span>). Bibliografia: DELG, s.v. <span class=\"greek\">ἕζομαι</span>.</p></section></article>\n<article id=\"entry-euprosopeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐπροσωπέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦euprosōpéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐπροσωπέω</span>. Primeiro aoristo <span class=\"greek\">εὐπροσώπησα</span>. De <span class=\"greek\">εὐπρόσωπος</span>, «de rosto bonito; de boa aparência»; ver <span class=\"greek\">πρόσωπον</span>. PTebt 19, 12 [114 a.C.] <span class=\"greek\">ὅπως</span> <span class=\"greek\">εὐπροσωπῶμεν</span>, «a fim de apresentarmos boa aparência». <strong>Causar boa impressão; apresentar uma imagem favorável</strong>, <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκί</span>, «perante as pessoas; na carne», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 6:12</a>. Bibliografia: DELG, s.v. <span class=\"greek\">ὄπωπα</span>; M-M; TW.</p></section></article>\n<article id=\"entry-eurakylon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρακύλων, ωνος, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eurakýlōn⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐρακύλων</span>, <span class=\"greek\">ωνος</span>, <span class=\"greek\">ὁ</span>. CIL VIII, 26652 apresenta «euroaquilo». Formação híbrida do vocabulário náutico latino-grego, composta de <span class=\"greek\">εὖρος</span> e do latim <em>aquilo</em> (B-D-F §5, 1d; §115, 1; Robertson 166). <strong>Vento do nordeste; euraquilão; vento nordeste</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.14\" target=\"_blank\" rel=\"noopener noreferrer\">At 27:14</a> (variante textual <span class=\"greek\">εὐροκλύδων</span>; ver esse lema). Bibliografia: J. Smith, <em>The Voyage and Shipwreck of St. Paul</em>, 4.ª ed. (1880), 119ss., 287ss.; Hemer, <em>Acts</em>, 141s.; Warnecke, <em>Romfahrt</em>, 37–39; M-M.</p></section></article>\n<article id=\"entry-heureteos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὑρετέος, α, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heuretéos⟧</span><span class=\"separator\">·</span><span>adjetivo verbal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὑρετέος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span>. Tucídides 3, 45, 4. <strong>Que deve ser descoberto ou encontrado.</strong> <span class=\"greek\">πῶς</span> <span class=\"greek\">πίστ</span>[<span class=\"greek\">ις</span>] <span class=\"greek\">εὑρ</span>[<span class=\"greek\">ετ</span>]<span class=\"greek\">έ̣</span>[<span class=\"greek\">α</span>], «como a fé deve ser discernida», Ox 1081, 32s. (cf. SJCh 90, 9–11, com sintaxe diferente). Conservar os colchetes da reconstrução e o diacrítico crítico da leitura original. Bibliografia: DELG, s.v. <span class=\"greek\">εὑρίσκω</span>.</p></section></article>\n<article id=\"entry-heurema-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὕρημα, ατος, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heúrēma⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὕρημα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span>. Ver o verbete seguinte. Trágicos, Heródoto e outros; POxy 472, 33 [séc. II d.C.]; Fílon; Josefo, C. Ap. 2, 148. A LXX utiliza a forma posterior <span class=\"greek\">εὕρεμα</span> (Frínico, p. 445s. Lob.; Dião Crisóstomo 59 [76], 1; ver Thackeray, p. 80). <strong>Descoberta; invenção</strong>, Dg 7:1. Bibliografia: DELG, s.v. <span class=\"greek\">εὑρίσκω</span>.</p></section></article>\n<article id=\"entry-heurisko-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὑρίσκω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heurískō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὑρίσκω</span>. Ver o verbete precedente. Homero e posteriores. <strong>Paradigma:</strong> imperfeito <span class=\"greek\">εὕρισκον</span> (também <span class=\"greek\">ηὕρισκον</span> em Êx 15:22; Dn 6:5 LXX; Melitão, P. [regularmente]); futuro <span class=\"greek\">εὑρήσω</span>; segundo aoristo <span class=\"greek\">εὗρον</span>, com formas mistas: primeira pessoa do plural <span class=\"greek\">εὕραμεν</span> (BGU 1095, 10 [57 d.C.]; Sb 6222, 12 [séc. III d.C.]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:2</a>; terceira pessoa do plural <span class=\"greek\">εὕροσαν</span> na LXX, -<span class=\"greek\">ωσαν</span> em GJs 24:3 (ver de Strycker, p. 247); <span class=\"greek\">εὕρησαν</span> em GJs 10:1 (ver de Strycker, p. 245); perfeito <span class=\"greek\">εὕρηκα</span>. <strong>Voz média:</strong> segundo aoristo <span class=\"greek\">εὑράμην</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:12</a> (B-D-F §81, 3; Mlt-H. 208). <strong>Voz passiva:</strong> presente <span class=\"greek\">εὑρίσκομαι</span>; imperfeito, terceira pessoa do singular <span class=\"greek\">ηὑρίσκετο</span>; primeiro futuro <span class=\"greek\">εὑρεθήσομαι</span> (W-S §15, s.v.); primeiro aoristo <span class=\"greek\">εὑρέθην</span> (também <span class=\"greek\">ηὑ</span>- na LXX); perfeito <span class=\"greek\">εὕρημαι</span>, LXX.</p><p class=\"entry-text\">① <strong>Deparar com alguma coisa, por procura deliberada ou casualmente: encontrar.</strong></p><p class=\"entry-text\">ⓐ <strong>Depois de procurar: achar; descobrir; encontrar.</strong> Uso absoluto, em oposição a <span class=\"greek\">ζητεῖν</span>, «procurar» (Platão, Gorg. 59, p. 503d; Epicteto 4, 1, 51 <span class=\"greek\">ζήτει</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εὑρήσεις</span>, «procura e encontrarás»; PTebt 278, 30 [séc. I d.C.] <span class=\"greek\">ζήτῶι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐχ</span> <span class=\"greek\">εὑρίσκωι</span>, «procuro e não encontro»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:7</a>s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:9</a>s.; Ox 654 (= ASyn. 247, 20), prefácio 5 [restauração de Fitzmyer]; GHb 70, 17.</p><p class=\"entry-text\"><strong>Com objeto pessoal e procura prévia:</strong> <span class=\"greek\">τινὰ</span> <span class=\"greek\">ζητεῖν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">εὑ</span>., «procurar alguém e encontrá-lo» (3Km 1:3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 1:17</a>. <strong>Procurar e não encontrar</strong>, <span class=\"greek\">τινὰ</span> ou <span class=\"greek\">τὶ</span> <span class=\"greek\">ζητεῖν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">οὐχ</span> <span class=\"greek\">εὑ</span>. (PGiss 21, 5; Sexto 28; 4Km 2:17; 2Esd 17:64; Sl 9:36; Pv 1:28; Ct 5:6; Ez 22:30; TestJob 40:7 <span class=\"greek\">ἐπιζητήσας</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">εὑρών</span>, «procurando-a e não a encontrando»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:43</a>; 26:60; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.55\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:55</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:24</a>; 13:6s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.34\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7:34</a>, 36; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 9:6</a>.</p><p class=\"entry-text\"><strong>Com acusativo de pessoa</strong>, <span class=\"greek\">εὑ</span>. <span class=\"greek\">τινά</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:45</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 2:13</a>. <strong>Com acusativo de coisa</strong>, <span class=\"greek\">τὶ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:14</a>; 13:46; 18:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24:3</a>. <span class=\"greek\">νομήν</span>, «pasto», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.9\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 10:9</a> (cf. Lm 1:6); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:11</a>; <span class=\"greek\">σπήλαιον</span>, «caverna», GJs 18:1; <span class=\"greek\">τὸ</span> <span class=\"greek\">πτῶμα</span>, «cadáver», GJs 24:3. <strong>Objeto acusativo subentendido pelo contexto:</strong> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">At 11:26</a>; GJs 21:2 (not pap — ressalva textual conservada como no original). <strong>Lugar indicado:</strong> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">φυλακῇ</span>, «na prisão», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:22</a>; <span class=\"greek\">πέραν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θαλάσσης</span>, «do outro lado do mar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.25\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6:25</a>.</p><p class=\"entry-text\"><strong>Voz passiva com negação:</strong> <span class=\"greek\">εἴ</span> <span class=\"greek\">τις</span> <span class=\"greek\">οὐχ</span> <span class=\"greek\">εὑρέθη</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">βίβλῳ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">γεγραμμένος</span>, «se alguém não foi achado inscrito no livro da vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 20:15</a> (cf. PHib 48, 6 [255 a.C.] <span class=\"greek\">οὐ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">εὑρίσκω</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">βιβλίοις</span>, «pois não encontro nos livros»; 2Esd 18:14). <strong>A passiva negada também pode significar deixar de ser encontrado apesar de busca minuciosa: desaparecer</strong> (PRein 11, 11 [séc. III a.C.]). Sobre Enoque, <span class=\"greek\">οὐχ</span> <span class=\"greek\">ηὑρίσκετο</span>, «não era encontrado», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:5</a> (Gn 5:24). <span class=\"greek\">ὄρη</span> <span class=\"greek\">οὐχ</span> <span class=\"greek\">εὑρέθησαν</span>, «as montanhas não foram encontradas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 16:20</a>; cf. 18:21.</p><p class=\"entry-text\"><strong>Dificuldade textual em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 3:10</a>:</strong> a adição da negação, efetivamente encontrada na versão saídica, esclareceria a leitura mais bem atestada e difícil: <span class=\"greek\">καὶ</span> <span class=\"greek\">γῆ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῇ</span> <span class=\"greek\">ἔργα</span> <span class=\"greek\">εὑρεθήσεται</span>, «e a terra e as obras nela serão encontradas»; outras propostas em Nestle. Ver também Danker na acepção ② abaixo.</p><p class=\"entry-text\">ⓑ <strong>Casualmente, sem procurar: encontrar; deparar com alguém ou alguma coisa.</strong> Com acusativo <span class=\"greek\">τινά</span>, «alguém» (PGen 54, 31 <span class=\"greek\">εὑρήκαμεν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πραιπόσιτον</span>, «encontramos o praepositus»; Gn 4:14s.; 18:28ss.; 1Km 10:2; 3Km 19:19; Sir 12:17; TestSol 18:21; Justino, A II, 11, 3): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:28</a>; 27:32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.41\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1:41</a>a (Diógenes Laércio 1, 109 <span class=\"greek\">τὸν</span> <span class=\"greek\">ἀδελφὸν</span> <span class=\"greek\">εὑρών</span>, «deparando com seu irmão»), 43, 45; 5:14; 9:35; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:6</a>; 18:2; 19:1; 28:14.</p><p class=\"entry-text\"><strong>Com <span class=\"greek\">ἐν</span> + dativo para indicar o lugar</strong> (3Km 11:29; 2Cr 21:17; 1Mc 2:46; Herodiano 3, 8, 6), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 2:14</a>. <strong>Com acusativo <span class=\"greek\">τὶ</span>, «alguma coisa»</strong> (Gn 11:2; 26:19; Jz 15:15; 4Km 4:39 e outros; Justino, D. 86, 5): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:44</a> (Biogr., p. 324 <span class=\"greek\">εὑρὼν</span> <span class=\"greek\">θησαυρόν</span>, «encontrando um tesouro»); 17:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 12:14</a> (Fócio, Bibl. 94, p. 74b, sobre Jâmblico, <em>Erot.</em> [Hercher I 222, 38] <span class=\"greek\">εὑρόντες</span> <span class=\"greek\">ὄνους</span> <span class=\"greek\">δύο</span> <span class=\"greek\">ἐπέβησαν</span>, «encontrando dois jumentos, montaram-nos»); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 17:23</a>.</p><p class=\"entry-text\"><strong>Voz passiva: ser encontrado; achar-se; estar</strong> (Dt 20:11; 4Km 14:14; 1Esd 1:19; 8:13; Bar 1:7; TestSol 7:6; GrBar 4:11). <span class=\"greek\">Φ</span>. <span class=\"greek\">εὑρέθη</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Ἄζωτον</span>, «Filipe encontrou-se [ou estava] em Azoto», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.40\" target=\"_blank\" rel=\"noopener noreferrer\">At 8:40</a> (cf. Est 1:5 <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἔθνεσιν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">εὑρεθεῖσιν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πόλιν</span>, «aos povos que estavam na cidade»; ver também 4Km 2). Por outro lado, uma expressão semítica, אֱשְׁתַּכַּח בְּ, «chegar a [um lugar]», pode subjazê-la, aqui e em <span class=\"greek\">εὑρεθῆναι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">βασιλείαν</span>, «ser encontrado/chegar ao Reino», Hs 9, 13, 2 (M. Black, «Aramaic Studies and the NT», JTS 49 [1948], 164).</p><p class=\"entry-text\"><span class=\"greek\">οὐδὲ</span> <span class=\"greek\">τόπος</span> <span class=\"greek\">εὑρέθη</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οὐρανῷ</span>, «já não se encontrou lugar para eles no céu», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 12:8</a> (ver Dn 2:35, Teodocião); cf. 18:22, 24. <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">εὑρέθη</span> <span class=\"greek\">δόλος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">στόματι</span> <span class=\"greek\">αὐτοῦ</span>, «nem se achou dolo na boca dele», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 2:22</a>; 1Cl 16:10 (ambos Is 53:9); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 14:5</a> (cf. Sf 3:13). <span class=\"greek\">ἵνα</span> <span class=\"greek\">εὑρεθῶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> (isto é, <span class=\"greek\">Χριστῷ</span>), «a fim de ser achado em Cristo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 3:9</a> (J. Moffatt, ET 24 [1913], 46).</p><p class=\"entry-text\">ⓒ <strong>Com acusativo e particípio ou adjetivo:</strong> designa o estado ou a ação em que alguém ou alguma coisa se encontra ou está envolvido (B-D-F §416, 2; Robertson 1120s.): <strong>achar; descobrir</strong>.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. <strong>Com particípio</strong> (Tucídides 2, 6, 3; Demóstenes 19, 332; Epicteto 4, 1, 27; PTebt 330, 5 [séc. II d.C.] <span class=\"greek\">παραγενομένου</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κώμην</span> <span class=\"greek\">εὗρον</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οἰκίαν</span> <span class=\"greek\">μου</span> <span class=\"greek\">σεσυλημένην</span>, «quando cheguei à aldeia, encontrei minha casa saqueada»; Nm 15:32; Tb 7:1 S; 8:13; Dn 6:14; 6:12, Teodocião; TestSol 1:5 D; TestAbr A 5, p. 82, 25 [Stone p. 12]; B 2, p. 109, 15 [Stone p. 60]; TestJob 37:8; ParJer 7:29 e outros; Josefo, Bell. 6, 136 <span class=\"greek\">τ</span>. <span class=\"greek\">φύλακας</span> <span class=\"greek\">εὗρον</span> <span class=\"greek\">κοιμωμένους</span>, «encontraram os guardas dormindo»; Atenágoras 33, 1). <span class=\"greek\">εὑρίσκει</span> <span class=\"greek\">σχολάζοντα</span>, «encontra-a desocupada» (condição que torna possível o retorno, H. Nyberg, ConNeot 2 [1936], 22–35), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:44</a>. <span class=\"greek\">εὗρεν</span> <span class=\"greek\">ἄλλους</span> <span class=\"greek\">ἑστῶτας</span>, «encontrou outros que estavam de pé», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:6</a> (cf. Jdt 10:6); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:2</a>; 24:46; 26:40, 43; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 11:2</a>; 13:36; 14:37, 40; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:12</a>; 7:10; 8:35; 11:25; 12:37, 43; 19:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:23</a>; 9:2; 10:27; 27:6; 2Cl 6:9; ITr 2:2 e frequentemente.</p><p class=\"entry-text\"><span class=\"greek\">εὗρεν</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">ὀγκωμένην</span>, «encontrou-a grávida», GJs 13:1a; 15:2. <span class=\"greek\">εὗρον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αἷμα</span> (<span class=\"greek\">πτῶμα</span> no papiro) <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">λίθον</span> <span class=\"greek\">γεγενημένον</span>, «encontraram seu sangue [no papiro: cadáver] transformado em pedra», GJs 24:3. <span class=\"greek\">εὗρον</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">ζῶντα</span>, «encontraram-no ainda vivo», AcPl Ha 10, 12; <span class=\"greek\">εὑρήσετε</span> <span class=\"greek\">δύο</span> <span class=\"greek\">ἄνδρας</span> <span class=\"greek\">προσευχομένους</span>, «encontrareis dois homens orando», ibid., 19.</p><p class=\"entry-text\"><strong>Com elipse do particípio:</strong> <span class=\"greek\">εὑρέθη</span> <span class=\"greek\">μόνος</span> (<span class=\"greek\">ὤν</span> subentendido), «foi encontrado sozinho», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:36</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">ὄφις</span> … <span class=\"greek\">εὗρεν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Εὔαν</span> <span class=\"greek\">μόνην</span>, «a serpente encontrou Eva sozinha», GJs 13:1b. <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">εὑρίσκω</span> <span class=\"greek\">αἴτιον</span> (<span class=\"greek\">ὄν</span>), «não encontro causa alguma [que o torne culpado]», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:4</a>; cf. v. 22.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <strong>Com adjetivo</strong> (TestAbr A 12, p. 91, 24 [Stone p. 30] <span class=\"greek\">εὗρεν</span> <span class=\"greek\">αὐτῆς</span> <span class=\"greek\">ζυγίας</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἁμαρτίας</span>, «achou equilibrados os seus pecados»; ApcMos 16): <span class=\"greek\">εὗρον</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">νεκράν</span>, «encontraram-na morta», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:10</a> (TestJob 40:11). <span class=\"greek\">εὕρωσιν</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ἀπαρασκευάστους</span>, «encontrem-vos despreparados», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 9:4</a>.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. <strong>Elipticamente, com uma oração inteira:</strong> <span class=\"greek\">οὐχ</span> <span class=\"greek\">οἵους</span> <span class=\"greek\">θέλω</span> <span class=\"greek\">εὕρω</span> <span class=\"greek\">ὑμᾶς</span>, «posso encontrar-vos não como desejo [encontrar-vos]», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 12:20</a>. Diversas vezes com <span class=\"greek\">καθώς</span>: <span class=\"greek\">εὗρον</span> <span class=\"greek\">καθὼς</span> <span class=\"greek\">εἶπεν</span> <span class=\"greek\">αὐτοῖς</span>, «encontraram [tudo] como lhes havia dito», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19:32</a>; GJs 15:2; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:13</a>. <span class=\"greek\">ἵνα</span> … <span class=\"greek\">εὑρεθῶσιν</span> <span class=\"greek\">καθὼς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡμεῖς</span>, «a fim de que sejam encontrados [vivendo do mesmo modo] que nós», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 11:12</a>.</p><p class=\"entry-text\">② <strong>Descobrir intelectualmente mediante reflexão, observação, exame ou investigação: encontrar; descobrir.</strong> Sentido transferido da acepção ① (Xenofonte, Hell. 7, 4, 2; Marco Aurélio 7, 1; Wsd 3:5; Dn 1:20, Teodocião; Josefo, Ant. 10, 196; Justino, A I, 31, 7 e outros; Atenágoras 17, 2, «criar» uma obra artística).</p><p class=\"entry-text\"><strong>Com acusativo de coisa:</strong> <span class=\"greek\">τὶ</span>, «alguma coisa». «Acho [que essa é] a regra», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7:21</a>. <span class=\"greek\">ὧδε</span> <span class=\"greek\">εὑ</span>. <span class=\"greek\">ἐντολήν</span>, «encontro aqui um mandamento», B 9:5. <strong>Com objeto pessoal <span class=\"greek\">τινά</span> e particípio seguinte:</strong> descobrir alguém fazendo algo (Anonymi Vi. Platonis, p. 7, 18 Westermann), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.29\" target=\"_blank\" rel=\"noopener noreferrer\">At 23:29</a>. Analogamente, com acusativo de coisa <span class=\"greek\">τὶ</span> e particípio, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 3:2</a>; com acusativo de pessoa <span class=\"greek\">τινά</span> e adjetivo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:2</a>. <strong>Seguido de <span class=\"greek\">ὅτι</span></strong> (TestSol 22:11), B 16:7.</p><p class=\"entry-text\"><strong>Resultado de investigação judicial:</strong> <span class=\"greek\">εὑ</span>. <span class=\"greek\">αἰτίαν</span> <span class=\"greek\">θανάτου</span>, «encontrar motivo para a pena de morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:28</a>. <span class=\"greek\">εὑ</span>. <span class=\"greek\">αἰτίαν</span>, <span class=\"greek\">κακόν</span>, <span class=\"greek\">ἀδίκημα</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, «encontrar causa, mal ou injustiça em alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.38\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 18:38</a>; 19:4, 6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 23:9</a>. <span class=\"greek\">εἰπάτωσαν</span> <span class=\"greek\">τί</span> <span class=\"greek\">εὗρον</span> <span class=\"greek\">ἀδίκημα</span>, «que digam que injustiça descobriram», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 24:20</a>. <span class=\"greek\">ποιεῖτε</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">εὑρεθῆτε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμέρᾳ</span> <span class=\"greek\">κρίσεως</span>, «procedei de modo que sejais aprovados no dia do julgamento», B 21:6.</p><p class=\"entry-text\"><strong>Sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 3:10</a>:</strong> cf. uma emenda conjectural <span class=\"greek\">καὶ</span> <span class=\"greek\">γῇ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὰ</span> (em lugar de <span class=\"greek\">καὶ</span> <span class=\"greek\">γῆ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰ</span>) <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῇ</span> <span class=\"greek\">ἔργα</span> <span class=\"greek\">εὑρεθήσεται</span>, «e a terra será julgada de acordo com as obras feitas nela» (cf. PsSol 17:8; F. Danker, ZNW 53 [1962], 82–86). Trata-se de proposta textual, não de leitura transmitida pacificamente.</p><p class=\"entry-text\"><strong>Com acusativo de preço ou medida calculada:</strong> <span class=\"greek\">εὗρον</span>, «encontraram», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:19</a>; 27:28.</p><p class=\"entry-text\"><strong>Seguido de pergunta indireta:</strong> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5:19</a>. Pelo uso do artigo, a oração interrogativa pode tornar-se objeto acusativo: <span class=\"greek\">εὑ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">τί</span> <span class=\"greek\">ποιήσωσιν</span>, «encontrar o que fazer», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19:48</a>; <span class=\"greek\">τὸ</span> <span class=\"greek\">πῶς</span> <span class=\"greek\">κολάσωνται</span> <span class=\"greek\">αὐτούς</span>, «como castigá-los», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 4:21</a>.</p><p class=\"entry-text\"><strong>Seguido de infinitivo:</strong> <span class=\"greek\">ἵνα</span> <span class=\"greek\">εὕρωσιν</span> <span class=\"greek\">κατηγορεῖν</span> <span class=\"greek\">αὐτοῦ</span>, «para encontrar uma acusação contra ele», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:7</a>; 11:54, códice D. Contudo, falta acusativo com <span class=\"greek\">εὕρωσιν</span> (cf. PParis 45, 7 [153 a.C.] <span class=\"greek\">προσέχων</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">εὕρῃ</span> <span class=\"greek\">τι</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">σοῦ</span> <span class=\"greek\">ἰπῖν</span> = <span class=\"greek\">εἰπεῖν</span>, «cuidando para que não encontre algo a dizer contra ti»). Por isso, talvez seja preferível concluir que <span class=\"greek\">εὑρίσκω</span> com infinitivo significa <strong>ser capaz de</strong>, como Astrampsychus, p. 5, linha 14, <span class=\"greek\">εἰ</span> <span class=\"greek\">εὑρήσω</span> <span class=\"greek\">δανείσασθαι</span> <span class=\"greek\">ἄρτι</span>, «se serei capaz de tomar dinheiro emprestado agora»; p. 6, linha 72; p. 42, Dec. 87, 1. A tradução de Lucas seria então «para que fossem capazes de apresentar uma acusação contra ele».</p><p class=\"entry-text\"><strong>Da busca e encontro de Deus</strong> (Is 55:6; Wsd 13:6, 9; cf. Fílon, Spec. Leg. 1, 36; Leg. All. 3, 47), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.27\" target=\"_blank\" rel=\"noopener noreferrer\">At 17:27</a>. <strong>Voz passiva:</strong> <span class=\"greek\">εὑρέθην</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐμὲ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ζητοῦσιν</span>, «deixei-me encontrar pelos que não me procuravam», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 10:20</a> (Is 65:1).</p><p class=\"entry-text\"><strong>Como o hebraico נִמְצָא:</strong> <strong>ser encontrado; aparecer; mostrar-se; provar ser</strong> (Cássio Dião 36, 27, 6; SIG 736, 51; 1109, 73; 972, 65; POxy 743, 25 [2 a.C.]; ParJer 4:5; Josefo, Bell. 3, 114; Justino, A I, 4, 2; Taciano 41:3; Melitão, P. 82, 603; Atenágoras 24, 4). <span class=\"greek\">εὑρέθη</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">γαστρὶ</span> <span class=\"greek\">ἔχουσα</span>, «constatou-se que ela seria mãe», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:18</a>. <span class=\"greek\">εὑρέθη</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐντολὴ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">θάνατον</span> (<span class=\"greek\">οὖσα</span> subentendido), «o mandamento revelou-se para mim causa de morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7:10</a>. <span class=\"greek\">οὐχ</span> <span class=\"greek\">εὑρέθησαν</span> <span class=\"greek\">ὑποστρέψαντες</span>; «não se encontrou quem retornasse?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17:18</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.39\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 4:2</a> (cf. Sir 44:20); 15:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 5:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 2:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 1:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 5:4</a>; 1Cl 9:3; 10:1; B 4:14; Hm 3:5 e frequentemente.</p><p class=\"entry-text\"><span class=\"greek\">ἄσπιλοι</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">εὑρεθῆναι</span>, «ser achados irrepreensíveis diante dele», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 3:14</a>. <span class=\"greek\">σχήματι</span> <span class=\"greek\">εὑρεθεὶς</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἄνθρωπος</span>, «quando apareceu em forma humana», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2:7</a>. <span class=\"greek\">εὑρεθήσομαι</span> <span class=\"greek\">μαχόμνενος</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">νόμῳ</span> <span class=\"greek\">κυρίου</span> … <span class=\"greek\">εὑρεθήσομαι</span> <span class=\"greek\">παραδιδοὺς</span> <span class=\"greek\">ἀθῶον</span> <span class=\"greek\">αἷμα</span>, «serei encontrado combatendo a Lei do Senhor … serei encontrado entregando sangue inocente», GJs 14:1.</p><p class=\"entry-text\">③ <strong>Alcançar estado ou condição: encontrar para si; obter.</strong> Na literatura ática, emprega-se a voz média com este sentido (B-D-F §310, 1; Robertson 814; Frínico, p. 140 Lob.); na literatura aqui abrangida, a voz média ocorre nesta acepção somente em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:12</a>. Normalmente utiliza-se a voz ativa (poetas; Luciano, Lexiph. 18; LXX; Josefo, Ant. 5, 41).</p><p class=\"entry-text\"><strong>Com acusativo <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχήν</span></strong>, «a própria vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:39</a>; 16:25. <strong>Com <span class=\"greek\">ἀνάπαυσιν</span></strong>, «repouso» (Sir 11:19; 22:13; 28:16; 33:26; <span class=\"greek\">ἄνεσιν</span>, «alívio», ApcEsdr 5:10), <span class=\"greek\">ταῖς</span> <span class=\"greek\">ψυχαῖς</span> <span class=\"greek\">ὑμῶν</span>, «para vossas almas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:29</a>. <span class=\"greek\">μετανοίας</span> <span class=\"greek\">τόπον</span>, «obter oportunidade de arrependimento» ou «de fazer mudar a opinião [do pai]», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:17</a>. <span class=\"greek\">σκήνωμα</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">Ἰακώβ</span>, «garantir uma habitação para o Deus de Jacó», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.46\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:46</a>b (Sl 131:5).</p><p class=\"entry-text\"><strong>Com <span class=\"greek\">χάριν</span>: obter graça ou favor</strong> (Ct 8:10, variante de leitura), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:16</a>. <span class=\"greek\">χάριν</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, «obter favor diante de Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:30</a>; também <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.46\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:46</a>a; GJs 11:2 (na LXX, via de regra, <span class=\"greek\">ἐναντίον</span> com genitivo; JosAs 15:14 <span class=\"greek\">ἐνώπιόν</span> <span class=\"greek\">σου</span>). <span class=\"greek\">ἔλεος</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">κυρίου</span>, «obter misericórdia do Senhor», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 1:18</a> (cf. Gn 19:19; Dn 3:38).</p><p class=\"entry-text\"><strong>Nota de crítica textual:</strong> a restauração [<span class=\"greek\">πίστιν</span> <span class=\"greek\">εὑρ</span>]<span class=\"greek\">ίσκομεν</span>, Ox 1081, 26, não é válida. Com base no texto copta de SJCh 90, 2, deve-se ler, com Till, p. 220, aparato, [<span class=\"greek\">ταῦτα</span> <span class=\"greek\">γιγν</span>]<span class=\"greek\">ῴσκομεν</span>. Preservam-se os colchetes por assinalarem reconstrução editorial.</p><p class=\"entry-text\"><strong>Bibliografia:</strong> B. 765; RAC VI 985–1052; DELG; M-M; EDNT; TW.</p></section></article>\n<article id=\"entry-euroklydon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐροκλύδων, ωνος, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦euroklýdōn⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐροκλύδων</span>, <span class=\"greek\">ωνος</span>, <span class=\"greek\">ὁ</span>. <strong>Euroclidom</strong>, explicado como vento do sudeste que levanta as ondas. Outra forma é <span class=\"greek\">εὐρυκλύδων</span>, «vento que levanta largas ondas». Apenas em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.14\" target=\"_blank\" rel=\"noopener noreferrer\">At 27:14</a>, como <strong>variante textual</strong>; <span class=\"greek\">εὐρακύλων</span> (ver esse lema) é considerada a leitura correta, e as outras duas formas provavelmente devem ser tratadas como erros de escribas. Entretanto, ver Etymol. Magn. 772, 30, s.v. <span class=\"greek\">τυφών</span>: <span class=\"greek\">τυφὼν</span> <span class=\"greek\">γάρ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀνέμου</span> <span class=\"greek\">σφόδρα</span> <span class=\"greek\">πνοή</span>, <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εὐρυκλύδων</span> <span class=\"greek\">καλεῖται</span>, «tufão é o sopro violento do vento, também chamado euriclídon». A forma <span class=\"greek\">εὐροκλύδων</span> é defendida por A. Acworth, JTS, nova série 24 (1973), 190–92, mas sem evidência externa; contra ele, C. Hemer, ibid. 26 (1975), 100–111; ver também Warnecke, <em>Romfahrt</em>, 37s., nota 17.</p></section></article>\n<article id=\"entry-euryklydon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρυκλύδων</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦euryklýdōn⟧</span><span class=\"separator\">·</span><span>forma remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐρυκλύδων</span>. <strong>Ver <span class=\"greek\">εὐροκλύδων</span>.</strong> Entrada remissiva autônoma; nenhuma acepção adicional é apresentada no original.</p></section></article>\n<article id=\"entry-eurychoros-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐρύχωρος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eurýchōros⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐρύχωρος</span>, <span class=\"greek\">ον</span>. <strong>Que possui muito espaço: largo; amplo; espaçoso</strong> (Aristóteles, HA 10, 5, p. 637a, 32; Diodoro Sículo 19, 84, 6; LXX; TestAbr A 88, 30 [Stone p. 24]; JosAs 24:21 [códice A e Pal. 364]; Fílon, Sacr. Abel. 61; Josefo, Ant. 1, 262; SibOr 3, 598). <strong>De caminho: espaçoso</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:13</a>. Substantivado, <span class=\"greek\">τὸ</span> <span class=\"greek\">εὐ</span>., <strong>um cômodo amplo</strong> (Apiano, Bell. Civ. 4, 41 §171; 2Cr 18:9; 1Esd 5:46), em que é possível viver com conforto e sem incômodo (cf. Sl 30:9 <span class=\"greek\">ἐν</span> <span class=\"greek\">εὐρυχώρῳ</span>; Os 4:16), Hm 5, 1, 2. Bibliografia: DELG, s.v. <span class=\"greek\">χώρα</span>; M-M; TW.</p></section></article>\n<article id=\"entry-eusebeia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσέβεια, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eusébeia⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐσέβεια</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span>. Ver o verbete seguinte e <span class=\"greek\">σέβομαι</span>. Pré-socráticos, Ésquilo e outros; inscrições, papiros, com o sentido de «piedade; reverência; lealdade [demonstrada para com pais ou divindades]; temor de Deus». Em oposição a <span class=\"greek\">πονηρός</span>, Diodoro Sículo 5, 79, 2. Cf. Diógenes Laércio 3, 83: pessoas piedosas observam os costumes sacrificiais e cuidam dos templos. Assim, Eneias é reiteradamente chamado <em>pius</em> na <em>Eneida</em> de Virgílio (A. Michels, ClJ 92 [1997], 399–416).</p><p class=\"entry-text\"><strong>Na literatura aqui abrangida e na LXX, somente quanto ao respeito reverencial tributado a Deus: devoção; piedade; temor reverente; vida piedosa.</strong> Platão, Rep. 10, 615c, <span class=\"greek\">εἰς</span> <span class=\"greek\">θεούς</span> [com <span class=\"greek\">γονέας</span>, «pais»]; Xenofonte, Cyr. 8, 1, 25; Posidônio 87 Fgm. 59, 107 <span class=\"greek\">περὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">δαιμόνιον</span>; Diodoro Sículo 4, 39, 1 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>; 7, 14, 6; 19, 7, 3; Epicteto, Ench. 31, 1 <span class=\"greek\">περὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεούς</span>; Herm. Wr. 4, 7 <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεόν</span>; inscrições [índices SIG e OGI]; UPZ 41, 10 [161/160 a.C.] <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θεῖον</span>; PHerm 52:19; PTebt 298, 45; PGiss 66, 10; LXX, especialmente 4Mc; TestSol 8:9; TestJud 18:5; TestIss 7:5; EpArist 2; 42 <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεὸν</span> <span class=\"greek\">ἡμῶν</span> e outros; Fílon, Deus Imm. 17 <span class=\"greek\">πρὸς</span> <span class=\"greek\">θεόν</span>; 69; Poster. Cai. 181; Josefo, Ant. 18, 117; C. Ap. 1, 162 <span class=\"greek\">περὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θεῖον</span>; Atenágoras 28, 2 [cf. 30, 3 <span class=\"greek\">περὶ</span> <span class=\"greek\">αὐτούς</span>]; Justino; Atenágoras. Com <span class=\"greek\">ἀνδρεία</span> e <span class=\"greek\">σοφία</span>, Orígenes, C. Cels. 8, 17, 16; Teófilo de Antioquia; Hipólito.</p><p class=\"entry-text\"><span class=\"greek\">ἰδίᾳ</span> <span class=\"greek\">εὐσεβείᾳ</span>, «por nossa própria piedade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">At 3:12</a>; cf. <span class=\"greek\">διὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἡμετέρας</span> <span class=\"greek\">εὐ</span>., «mediante nossa piedade», 1Cl 32:4. <span class=\"greek\">ἐν</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">εὐ</span>., «em toda piedade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 2:2</a>; cf. 4:7s.; 6:5s., 11. <span class=\"greek\">μετ</span>’ <span class=\"greek\">εὐσεβείας</span>, «com piedade», 1Cl 15:1 (cf. 2Mc 12:45). <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">εὐσέβειαν</span>, «as coisas pertinentes à piedade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 1:3</a> (cf. Josefo, Ant. 11, 120 <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θρησκείαν</span>). <span class=\"greek\">ἔχειν</span> <span class=\"greek\">μόρφωσιν</span> <span class=\"greek\">εὐσεβείας</span>, «ter a forma exterior de piedade», isto é, «ser devoto somente na aparência», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 3:5</a> (cf. Fílon, Plant. 70 <span class=\"greek\">εἰσί</span> <span class=\"greek\">τινες</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐπιμορφαζόντων</span> <span class=\"greek\">εὐσέβειαν</span>). Com <span class=\"greek\">φιλοξενία</span>, «hospitalidade», 1Cl 11:1.</p><p class=\"entry-text\"><strong>A piedade como resultado da perseverança e causa do amor fraterno</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 1:6</a>s. (sobre a lista de virtudes, cf. Luciano, Somn. 10; OGI 438; Deissmann, LO 270 [LAE 322]). <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χριστῷ</span> <span class=\"greek\">εὐ</span>., «a piedade cristã», 1Cl 1:2. <span class=\"greek\">περὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">εὐ</span>. <span class=\"greek\">φιλοπονεῖν</span>, «dedicar esforços à piedade», 2Cl 19:1.</p><p class=\"entry-text\"><strong>Respeito à divindade; devoção</strong> (Diodoro Sículo 16, 60, 3; Josefo, C. Ap. 1, 60): <span class=\"greek\">ἡ</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">εὐσέβειαν</span> <span class=\"greek\">διδασκαλία</span>, «ensino de acordo com a piedade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 6:3</a>; <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀλήθεια</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">εὐ</span>., «a verdade segundo a piedade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1:1</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">εὐ</span>. <span class=\"greek\">μυστήριον</span>, «o mistério da piedade», também «o fundamento de nossa piedade» ou «o segredo da devoção a Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 3:16</a> (ver M. Massinger, <em>Bibliotheca Sacra</em> 96 [1940], 479–89).</p><p class=\"entry-text\"><strong>Plural: atos de piedade</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 3:11</a> (cf. PGM 13, 717; Justino, D. 47, 2).</p><p class=\"entry-text\"><strong>Bibliografia:</strong> O. Kern, <em>D. Rel. der Griechen</em> I (1926), 273–90; F. Bräuninger, <em>Unters. zu d. Schriften des Hermes Trismeg.</em>, tese, Berlim (1926), especialmente sobre <span class=\"greek\">εὐσέβεια</span> e <span class=\"greek\">γνῶσις</span>; F. Tillmann, <em>Past. Bonus</em> 53 (1942), 129–36, 161–65 («Frömmigkeit» nas Pastorais); W. Foerster, NTS 5 (1959), 213–18 (Pastorais). Ver também <span class=\"greek\">ὅσιος</span>, fim do verbete. B. 1462; Larfeld I 496; DELG, s.v. <span class=\"greek\">σέβομαι</span>; M-M; TW; Sv.</p></section></article>\n<article id=\"entry-eusebeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσεβέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eusebéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐσεβέω</span>. Futuro, terceira pessoa do plural <span class=\"greek\">εὐσεβήσουσι</span>, Sus 64 LXX; aoristo, terceira pessoa do plural <span class=\"greek\">εὐσέβησαν</span>, 4Mc 9:6. Ver o verbete precedente. Teógnis, trágicos e outros; inscrições, papiros, LXX; Justino; Orígenes. «Ser reverente, respeitoso, devoto» (com <span class=\"greek\">εἰς</span>, <span class=\"greek\">πρός</span> ou <span class=\"greek\">περί</span> <span class=\"greek\">τινα</span>). <strong>Na literatura aqui abrangida, somente com acusativo:</strong> manifestar reverência incomum ou respeito profundo por alguém (trágicos e outros; inscrições; LXX).</p><p class=\"entry-text\"><span class=\"greek\">εὐ</span>. indica o senso de obrigação reverencial que surge num sistema de reciprocidade, no qual se manifesta respeito especial àqueles cujo investimento no bem-estar de alguém é maior, como divindades ou figuras paternas.</p><p class=\"entry-text\">ⓐ <strong>Acerca de seres divinos: manifestar devoção excepcional; prestar culto</strong> (Ésquilo, Ag. 338 <span class=\"greek\">τοὺς</span> <span class=\"greek\">θεούς</span>; SIG 814, 36 <span class=\"greek\">εὐσεβῶν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεούς</span>; Sb 6828, 7; 4Mc 11:5; Fílon, Spec. Leg. 1, 312; Praem. 40; Josefo, Ant. 10, 45; C. Ap. 2, 125 <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>): <span class=\"greek\">ὸ̔</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">ἀγνοοῦντες</span> <span class=\"greek\">εὐσεβεῖτε</span>, «aquilo que, sem conhecer, adorais», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 17:23</a>.</p><p class=\"entry-text\">A passagem não se refere a um culto formal, mas ao desejo de assegurar reconhecimento apropriado ao poder transcendente, atestado pela palavra <span class=\"greek\">δεισιδαιμονέστερος</span> no v. 22. Os atenienses manifestam uma espécie de teologia de «carta coringa» mediante a instalação de um altar especial.</p><p class=\"entry-text\">ⓑ <strong>Acerca de seres humanos, sobretudo pais ou antepassados:</strong> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἴδιον</span> <span class=\"greek\">οἶκον</span> <span class=\"greek\">εὐ</span>., «mostrar especial respeito aos membros da própria família», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 5:4</a>. Bibliografia: M-M; TW.</p></section></article>\n<article id=\"entry-eusebes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσεβής, ές</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eusebḗs⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐσεβής</span>, <span class=\"greek\">ές</span>. Ver o verbete precedente. Teógnis, Píndaro e outros; inscrições, papiros, LXX. <strong>Que manifesta reverência ou respeito profundo: devoto; piedoso; temente a Deus; reverente.</strong> Na literatura aqui abrangida, exclusivamente quanto ao relacionamento com Deus (Platão, Euthyphr. 5c; Phlb. 39e; Xenofonte, Apol. 19; Mem. 4, 6, 4; 4, 8, 11; Epicteto 2, 17, 31; Luciano, De Calumn. 14; SIG 821c, 3; 1052, 5 <span class=\"greek\">μύσται</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐπόπται</span> <span class=\"greek\">εὐ</span>., «iniciados e espectadores devotos»; LXX; En; EpArist 233; Fílon, Leg. All. 3, 209 e outros; Josefo, Ant. 9, 236; Ar. [Milne 76, 36]; Justino; Melitão, HE 4, 26, 10). <span class=\"greek\">στρατιώτης</span> <span class=\"greek\">εὐ</span>., «soldado piedoso», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 10:7</a>; com <span class=\"greek\">φοβούμενος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεόν</span>, «temente a Deus», v. 2. <span class=\"greek\">πεποίθησις</span>, «confiança piedosa», 1Cl 2:3.</p><p class=\"entry-text\"><strong>Uso substantivado</strong>, <span class=\"greek\">ὁ</span> <span class=\"greek\">εὐ</span>., «a pessoa piedosa; o devoto» (Xenofonte, Mem. 4, 6, 2; Cyr. 8, 1, 25; Diodoro Sículo 1, 92, 5 <span class=\"greek\">οἱ</span> <span class=\"greek\">εὐσεβεῖς</span>; SEG VIII, 550, 4 [séc. I a.C.], plural = devotos de Ísis; Sir 12:4; 39:27; Pv 13:19; Ec 3:16, variante textual; En 102:4; 103:3; PsSol 13:5; TestLevi 16:2; Justino, A I, 2, 1 <span class=\"greek\">τοὺς</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">ἀλήθειαν</span> <span class=\"greek\">εὐ</span>.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 2:9</a>; 2Cl 19:4. <span class=\"greek\">χῶρος</span> <span class=\"greek\">εὐσεβῶν</span>, «lugar entre os piedosos» (ver <span class=\"greek\">χῶρος</span> I), 1Cl 50:3. <span class=\"greek\">τὸ</span> <span class=\"greek\">εὐ</span>., «piedade», em contraste com <span class=\"greek\">τὸ</span> <span class=\"greek\">κερδαλέον</span>, «aquilo que traz lucro» (Sófocles, Oed. Col. 1127 e outros; Epicteto 1, 29, 52; Fílon, Agr. 128; Josefo, Ant. 12, 43; Justino, D. 98, 1), 2Cl 20:4. A dimensão moral é indicada pela referência subsequente a um «espírito injusto».</p><p class=\"entry-text\"><strong>Bibliografia:</strong> B. Easton, <em>Pastoral Epistles</em> (1947), 218. Ver também <span class=\"greek\">ὅσιος</span>, fim do verbete; M-M; TW.</p></section></article>\n<article id=\"entry-eusebos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσεβῶς</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eusebôs⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐσεβῶς</span>, advérbio de <span class=\"greek\">εὐσεβής</span>. Píndaro, Xenofonte, Platão e outros; inscrições, papiros, LXX. <strong>De maneira piedosa, em relação a Deus</strong> (frequente em inscrições [índice SIG]; 4Mc 7:21, variante; EpArist 37 e 261; Fílon, Aet. M. 10; Atenágoras 1:3 <span class=\"greek\">εὐσεβέστατα</span> <span class=\"greek\">διακειμένους</span>), 1Cl 61:2. Cf. Xenofonte, Mem. 4, 3, 16: «Existe maneira melhor ou mais reverente de honrar os deuses do que praticar aquilo que ordenam?»</p><p class=\"entry-text\">Com <span class=\"greek\">ζῆν</span>, «viver piedosamente», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 3:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 2:12</a> (cf. <span class=\"greek\">βιοῦν</span> <span class=\"greek\">εὐ</span>. em Ps.-Platão, Axioch. 372a). Com <span class=\"greek\">δικαίως</span>, «justamente» (SIG 772; Josefo, Ant. 8, 300; A. Burk, <em>Die Pädagogik des Isokrates …</em> [1923], 173, nota 2), 1Cl 62:1. Com <span class=\"greek\">δικ</span>. e <span class=\"greek\">σωφρόνως</span>, «sensatamente» (Sócrates, Ep. 15, 1 <span class=\"greek\">ἐβίωσε</span> <span class=\"greek\">σωφρόνως</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ὁσίως</span> <span class=\"greek\">κ</span>. <span class=\"greek\">εὐ</span>.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 2:12</a>. Bibliografia: M-M.</p></section></article>\n<article id=\"entry-eusemos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔσημος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eúsēmos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὔσημος</span>, <span class=\"greek\">ον</span>. De <span class=\"greek\">σῆμα</span>, «sinal»; ver <span class=\"greek\">σημαίνω</span>, <span class=\"greek\">σημεῖον</span>. Trágicos, Hipócrates e outros; inscrições, papiros; Sl 80:4. <strong>Facilmente reconhecível: claro; distinto; inteligível</strong> (Ésquilo, Suppl. 714; Teofrasto, Caus. Pl. 6, 19, 5; Artemidoro 2, 44 <span class=\"greek\">εὐσήμου</span> <span class=\"greek\">ὄντος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">λόγου</span>; Porfírio, Abst. 3, 4, referente à fala; OGI 90, 43; 665, 13). <span class=\"greek\">εὔ</span>. <span class=\"greek\">λόγον</span> <span class=\"greek\">διδόναι</span>, «proferir discurso inteligível», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 14:9</a>. Bibliografia: DELG, s.v. <span class=\"greek\">σῆμα</span>; M-M; TW.</p></section></article>\n<article id=\"entry-eusplanchnia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐσπλαγχνία, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eusplanchnía⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐσπλαγχνία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span>. Ver o verbete seguinte e <span class=\"greek\">σπλάγχνα</span>. Ps.-Eurípides, Rhes. 192; Teodoro Pródromo 8, 317; Nicetas Eugeniano 8, 238; PLond 1916, 31 [séc. IV d.C., cristão]; PCairMasp 97 verso D, 69; TestZeb 5:1 e outros; ApcSed 5:8 e outros. <strong>Ternura de coração; compaixão; benevolência.</strong> Com <span class=\"greek\">γλυκύτης</span>, «doçura» (como Teófilo de Antioquia, Ad Autol. 2, 14), 1Cl 14:3. Bibliografia: DELG, s.v. <span class=\"greek\">σπλήν</span>; M-M.</p></section></article>\n"};
